/**
 * generated by stackra gen from the consumed manifests' resources, widgets and documents (commerce
 * with its loyalty_kit and access_log modules; @stackra/queue) — do not edit
 * Purpose: resource, widget and document declarations as data for @stackra/panel, and the
 *          `Resources.*` route constants a route redirects to (`[Resources.Order.view, { id }]`).
 * Boundary: data only; actions, queries, permissions, override points, slots and events are the
 *           typed descriptors of `#stackra/clients`, `#stackra/slots` and `#stackra/panels`, never
 *           strings.
 * Runtime: browser
 */
import { SystemRole } from "@stackra/iam";
import {
  Column,
  Display,
  Entry,
  Field,
  Filter,
  SortDirection,
  WidgetSize,
  document,
  resource,
  widget,
} from "@stackra/panel";
import { Commerce } from "#stackra/clients";
import { I18n } from "#stackra/i18n";
import { Panels } from "#stackra/panels";
import { Slots } from "#stackra/slots";

/** Route constants per generated screen; `view`, `edit` and `create` are typed path builders. */
export const Resources = {
  Product: resource("catalogue.product", {
    base: "/catalogue/products",
    list: Commerce.queries.ListProducts,
    view: Commerce.queries.GetProduct,
    create: Commerce.actions.CreateProduct,
    update: Commerce.actions.UpdateProduct,
    permission: Commerce.permissions.Product.read,
  }),
  Order: resource("orders.order", {
    base: "/orders/orders",
    list: Commerce.queries.ListOrders,
    view: Commerce.queries.GetOrder,
    permission: Commerce.permissions.Order.read,
  }),
  AccessLogEntry: resource("access_log.access_log_entry", {
    base: "/access-log/entries",
    permission: Commerce.permissions.AccessLogEntry.read,
  }),
  FailedJob: resource("queue.failed_job", { base: "/queue/failed-jobs" }),
  SalesToday: document("orders.sales_today", {
    path: "/sales",
    permission: Commerce.permissions.Order.read,
  }),
} as const;

/** Every widget a consumed service declared, with its slot, query and refresh events. */
export const widgets = [
  widget(Commerce.widgets.LowStock, {
    slot: Slots.Dashboard.Main,
    size: WidgetSize.Md,
    query: Commerce.queries.ListLowStock,
    params: { limit: 5 },
    display: Display.list({ primary: "variantId", secondary: "available" }),
    permission: Commerce.permissions.Stock.read,
    refreshOn: [Commerce.events.StockLow],
  }),
  widget(Commerce.widgets.RevenueToday, {
    slot: Slots.Dashboard.Header,
    size: WidgetSize.Sm,
    query: Commerce.queries.OrdersToday,
    component: Commerce.overrides.RevenueSparkline,
    permission: Commerce.permissions.Order.read,
    roles: [SystemRole.Owner, SystemRole.Manager],
    refreshOn: [Commerce.events.OrderPaid],
  }),
] as const;

/** Every resource screen: columns, filters, form fields and row actions. */
export const resources = {
  "catalogue.product": {
    label: I18n.catalogue.resource.products,
    panels: [Panels.TenantAdmin],
    table: {
      columns: [
        Column.image("images", { first: true }),
        Column.text("title", { sortable: true, searchable: true }),
        Column.badge("status", { enum: Commerce.enums.ProductStatus }),
      ],
      filters: [Filter.select("status", { enum: Commerce.enums.ProductStatus })],
      rowActions: [Commerce.actions.ArchiveProduct],
    },
    form: {
      fields: [
        Field.text("title", { required: true }),
        Field.text("slug", { required: true }),
        Field.upload("images", {
          action: Commerce.actions.AttachProductImage,
          accept: ["image/png", "image/jpeg", "image/webp"],
          maxBytes: 5_000_000,
        }),
        Field.repeater("variants", [Field.text("sku", { required: true })]),
      ],
    },
    infolist: { entries: [Entry.text("title"), Entry.badge("status"), Entry.list("variants")] },
  },
  "orders.order": {
    label: I18n.orders.resource.orders,
    panels: [Panels.TenantAdmin, Panels.CustomerPortal],
    create: false,
    table: {
      columns: [
        Column.text("id", { copyable: true }),
        Column.custom("status", Commerce.overrides.OrderStatusBadge),
        Column.money("totals.totalMinor", { currencyField: "totals.currency", sortable: true }),
        Column.dateTime("createdAt", { sortable: true }),
      ],
      filters: [
        Filter.select("status", { enum: Commerce.enums.OrderStatus }),
        Filter.dateRange("createdAt"),
      ],
      defaultSort: { createdAt: SortDirection.Desc },
      rowActions: [Commerce.actions.CancelOrder],
      bulkActions: [Commerce.actions.CancelOrder],
    },
    infolist: {
      entries: [
        Entry.custom("status", Commerce.overrides.OrderStatusBadge),
        Entry.money("totals.subtotalMinor"),
        Entry.list("totals.adjustments", { columns: ["label", "amountMinor"] }),
        Entry.money("totals.totalMinor"),
        Entry.relation("lines"),
      ],
    },
  },
  "access_log.access_log_entry": {
    label: I18n.access_log.resource.entries,
    panels: [Panels.TenantAdmin],
    create: false,
    table: {
      columns: [
        Column.dateTime("at", { sortable: true }),
        Column.text("subject"),
        Column.text("action"),
      ],
      defaultSort: { at: SortDirection.Desc },
    },
  },
  "queue.failed_job": {
    label: I18n.queue.resource.failed_jobs,
    panels: [Panels.TenantAdmin],
    create: false,
    table: {
      columns: [
        Column.text("queue"),
        Column.text("job"),
        Column.dateTime("failedAt", { sortable: true }),
      ],
      defaultSort: { failedAt: SortDirection.Desc },
    },
  },
} as const;
